sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	var responseBreached =
current.getValue('response_breached') == 'true' ||
current.getValue('response_breached') == '1';

var resolutionBreached =
current.getValue('resolution_breached') == 'true' ||
current.getValue('resolution_breached') == '1';

if (!responseBreached && !resolutionBreached) {
return;
}

var newLevel = 0;

if (responseBreached) {
newLevel = 1;
}

if (resolutionBreached) {
newLevel = 3;
}

var currentLevel =
parseInt(current.getValue('escalation_level'), 10) || 0;

if (newLevel <= currentLevel) {
return;
}

var updateRecord = new GlideRecord(
'x_78515_intellig_0_major_incident'
);

if (updateRecord.get(current.getUniqueValue())) {

updateRecord.setWorkflow(false);

updateRecord.setValue(
'escalation_level',
String(newLevel)
);

updateRecord.setValue(
'escalated_at',
new GlideDateTime().getValue()
);

updateRecord.update();

// Generate escalation notification event
gs.eventQueue(
'x_78515_intellig_0.mim.escalation',
updateRecord,
String(newLevel),
updateRecord.getValue('short_description')
);

gs.info('MIM ESCALATION EVENT QUEUED: Level ' + newLevel);
}

})(current, previous);
